{
  "framework": "vite",
  "buildCommand": "npm run build",
  "outputDirectory": "dist",
  "installCommand": "npm ci",

  "headers": [
    {
      "source": "/static/(.*)",
      "headers": [
        { "key": "Cache-Control", "value": "public, max-age=31536000, immutable" }
      ]
    },
    {
      "source": "/(.*)",
      "headers": [
        { "key": "X-Frame-Options", "value": "DENY" },
        { "key": "X-Content-Type-Options", "value": "nosniff" }
      ]
    }
  ],

  "redirects": [
    {
      "source": "/old-path",
      "destination": "/new-path",
      "permanent": true
    }
  ],

  "rewrites": [
    {
      "source": "/api/(.*)",
      "destination": "https://api.myapp.com/$1"
    },
    {
      "source": "/(.*)",
      "destination": "/index.html"
    }
  ]
}

// Place in /api/ directory → automatically deployed as a serverless function
// Vercel supports Node.js serverless AND Edge runtime

// Edge function (runs at Vercel's global edge, ~0ms cold start):
export const config = { runtime: 'edge' };

export default function handler(req: Request) {
  const url = new URL(req.url);
  const name = url.searchParams.get('name') ?? 'World';

  return new Response(
    JSON.stringify({ message: `Hello, ${name}!`, region: process.env.VERCEL_REGION }),
    { headers: { 'Content-Type': 'application/json' } }
  );
}

